def backfill_payment_and_receipt_status(apps, schema_editor):
    """Derive the new independent statuses from immutable historical rows.

    No financial or stock history is edited. A purchase order paid by a
    SupplierPaymentRequest but not yet physically delivered is PAID + NOT_
    RECEIVED; a partially delivered order is PARTIALLY_RECEIVED even if the
    legacy status label says PAID.
    """
    PurchaseOrder = apps.get_model("inventory", "PurchaseOrder")
    PurchaseOrderPayment = apps.get_model("inventory", "PurchaseOrderPayment")
    db = schema_editor.connection.alias

    # Existing rows carrying a verified executed SupplierPaymentRequest are
    # already mirrored; they must not be reported as unposted exceptions.
    PurchaseOrderPayment.objects.using(db).exclude(accounting_settlement_reference="").update(
        accounting_posting_status="MIRRORED"
    )

    def dec(value):
        return Decimal(str(value or 0))

    for order in PurchaseOrder.objects.using(db).prefetch_related("lines", "payments").iterator(chunk_size=200):
        lines = list(order.lines.all())
        total = sum(
            (dec(line.quantity_ordered) * dec(line.unit_cost) for line in lines),
            Decimal("0.00"),
        ).quantize(Decimal("0.01"))
        paid = sum((dec(payment.amount) for payment in order.payments.all()), Decimal("0.00"))
        if total <= 0 or paid <= 0:
            payment_status = "UNPAID"
        elif paid >= total:
            payment_status = "PAID"
        else:
            payment_status = "PARTIALLY_PAID"

        delivered = lambda line: dec(line.quantity_received) + dec(line.quantity_damaged) + dec(line.quantity_rejected)
        if not lines:
            receipt_status = "NOT_RECEIVED"
        elif all(delivered(line) >= dec(line.quantity_ordered) for line in lines):
            receipt_status = "RECEIVED"
        elif any(delivered(line) > 0 for line in lines):
            receipt_status = "PARTIALLY_RECEIVED"
        else:
            receipt_status = "NOT_RECEIVED"

        PurchaseOrder.objects.using(db).filter(pk=order.pk).update(
            payment_status=payment_status, receipt_status=receipt_status,
        )


